hl.config({
    input = {
        -- DOS distribuciones cargadas en todos los teclados, en este orden:
        -- índice 0 = es, índice 1 = us. El portátil tiene serigrafía española,
        -- así que arranca en la primera. El teclado USB externo invierte el
        -- orden más abajo, en su `hl.device`.
        --
        -- Las dos tienen que estar en la lista para que Super+Espacio pueda
        -- alternar: `switchxkblayout next` ROTA entre las ya cargadas, no
        -- carga distribuciones nuevas.
        kb_layout  = "es,us",

        -- Las variantes van POSICIONALMENTE emparejadas con `kb_layout`: la
        -- primera está vacía (es, sin variante) y la segunda es `intl`, o sea
        -- US International con teclas muertas. Así la distribución americana
        -- da tildes, ñ y ç, y es la misma tanto aquí como en el teclado
        -- externo — un solo comportamiento que recordar. El porqué de `intl`
        -- y no `altgr-intl`, en el `hl.device` de abajo.
        kb_variant = ",intl",
        kb_model   = "",
        kb_options = "",
        kb_rules   = "",

        follow_mouse = 1,

        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.

        touchpad = {
            natural_scroll = true,
        },
    },
})

hl.gesture({
    fingers = 3,
	    direction = "horizontal",
    action = "workspace"
})

-- Config por dispositivo: ver
-- https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/
-- Aquí había un `hl.device` de ejemplo para "epic-mouse-v1", retirado el
-- 2026-08-27: no existe tal dispositivo. Los reales de este equipo son
-- `elan0305:00-04f3:31fd-mouse` y `elan0305:00-04f3:31fd-touchpad`
-- (`hyprctl devices`), así que ese bloque no se aplicaba a nada.

-- Teclado USB externo (SEMITEK USB-HID Gaming Keyboard, 1EA7:0907), de
-- distribución AMERICANA (2026-09-07). Orden invertido respecto al global:
-- índice 0 = us, índice 1 = es. Así cada teclado arranca en SU serigrafía.
--
-- Son DOS entradas porque el teclado expone dos endpoints HID y los dos emiten
-- teclas (`grep -A6 -i semitek /proc/bus/input/devices`: `input0` alfanumérico
-- e `input2`, que además hace de ratón; ambos con handler `kbd`). Poniéndolo
-- solo en el primero, parte de las teclas seguiría interpretándose en es.
--
-- El nombre es el de `hyprctl devices`, no el del USB: Hyprland lo pasa a
-- minúsculas y sustituye los espacios por guiones.
--
-- `us` va con variante `intl` (US International CON TECLAS MUERTAS), para poder
-- escribir tildes, ñ y ç desde la distribución americana. Emparejamiento
-- posicional otra vez, e invertido respecto al global porque aquí `us` va
-- primero: "intl," = us→intl, es→sin variante.
--
-- ⚠️ NO es `altgr-intl`, y es una decisión tomada PROBANDO LAS DOS el
-- 2026-09-07. La disyuntiva es qué se pone en el nivel base y qué en AltGr:
--
--   intl        ' " ` ~ ^ muertas en el base; tilde = ' + vocal
--   altgr-intl  ' " ` ~ ^ literales en el base; tilde = AltGr + ' + vocal
--
-- Gana `intl` porque los acentos se escriben mucho más a menudo que las
-- comillas, y porque **el nivel de AltGr de `intl` sigue dando el carácter
-- literal**: AltGr + ' = ', AltGr + Shift + ' = ", AltGr + ` = `,
-- AltGr + Shift + ` = ~, AltGr + Shift + 6 = ^. O sea que con `intl` no se
-- pierde nada, solo cambia qué cuesta una pulsación y qué cuesta dos. Con
-- `altgr-intl` sería al revés, y lo caro serían las tildes.
-- Ver /usr/share/X11/xkb/symbols/us; AltGr es el Alt DERECHO
-- (`include "level3(ralt_switch)"`).
for _, teclado in ipairs({
    "semitek-usb-hid-gaming-keyboard",
    "semitek-usb-hid-gaming-keyboard-1",
}) do
    hl.device({ name = teclado, kb_layout = "us,es", kb_variant = "intl," })
end

-- Lápiz y táctil de la pantalla (ELAN9024:00 04F3:4297) anclados al panel
-- interno (2026-09-12).
--
-- El digitalizador reporta coordenadas ABSOLUTAS sobre su propia superficie.
-- Sin `output`, Hyprland las estira sobre el ÁREA COMBINADA de todas las
-- salidas, no sobre el panel que estás tocando. Con el monitor externo puesto
-- esa área pasa a ser ~4160x1220 lógicos (`hyprctl monitors`: HDMI-A-1
-- 2560x1440 en -2560x-220 y eDP-1 2560x1600 a escala 1,6 = 1600x1000 en 0x0),
-- así que el trazo sale desplazado respecto a la punta del lápiz. Con un solo
-- monitor las dos áreas coinciden, y por eso sin HDMI calibra bien.
--
-- Son DOS entradas porque `hyprctl devices` los lista por separado: el lápiz
-- en `Tablets` (sufijo `-stylus`) y el dedo en `Touch` (sin sufijo).
for _, puntero in ipairs({
    "elan9024:00-04f3:4297-stylus", -- lápiz (sección Tablets)
    "elan9024:00-04f3:4297",        -- táctil (sección Touch)
}) do
    hl.device({ name = puntero, output = "eDP-1" })
end


---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
-- Bloqueo manual. Vía dbus, NO `hyprlock` directo: así hypridle recibe el
-- evento y lanza su `lock_cmd` (ver hypridle.conf). Sin `locked = true`: con la
-- sesión ya bloqueada no debe hacer nada.
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("loginctl lock-session"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("rofi -show drun"))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Selector de símbolos que no están en el teclado (griegas, operadores, flechas
-- y sub/superíndices), buscables por nombre en castellano. Escribe el elegido
-- en la ventana enfocada si hay `wtype`; si no, lo deja en el portapapeles.
-- Ver scripts/simbolos.sh. G de "griego".
hl.bind(mainMod .. " + G", hl.dsp.exec_cmd("simbolos"))

-- Alterna es/us EN EL TECLADO QUE PULSA EL ATAJO, sin tocar el otro: el estado
-- de xkb es por dispositivo. Ver scripts/kb-layout.sh.
-- Se resuelve por CÓDIGO de tecla, no por símbolo (`resolve_binds_by_sym` está
-- en su valor por defecto), así que el atajo sigue en la misma tecla física en
-- ambas distribuciones.
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd("kb-layout"))

-- Notificaciones (dunst, tarea 2.2).
-- `history-pop` recupera la última notificación cerrada; con
-- `sticky_history = yes` en dunstrc se queda fija hasta cerrarla, en vez de
-- volver a expirar en 5-10 s. El historial guarda 20 y VIVE EN MEMORIA: se
-- pierde entero si dunst se reinicia o se cierra la sesión.
-- Sin `locked = true` en ninguno de los dos: con la sesión bloqueada dunst
-- está pausado a propósito (ver on_lock_cmd en hypridle.conf), así que sacar
-- notificaciones del historial sobre hyprlock sería justo lo contrario.
hl.bind(mainMod .. " + N",           hl.dsp.exec_cmd("dunstctl history-pop"))
hl.bind(mainMod .. " + SHIFT + N",   hl.dsp.exec_cmd("dunstctl close-all"))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Alterna la salida de audio de TODO el sistema entre la interfaz USB (SSL 2+)
-- y los altavoces del portátil, sin desenchufar la interfaz. El script mueve
-- también los flujos que ya estaban sonando, cosa que `pactl set-default-sink`
-- por sí solo no hace. Ver scripts/audio-salida.sh.
hl.bind(mainMod .. " + Z", hl.dsp.exec_cmd("audio-salida"))

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
-- El "-p playerctld,%any" importa, y las dos partes hacen falta:
--   playerctld -> el player que usaste por ultima vez. Sin esto, playerctl
--                 actua sobre el primero que enumera y ese orden NO es estable:
--                 con Firefox y Spotify abiertos, el play/pause se lo llevaba
--                 Firefox unas veces si y otras no.
--   %any       -> cualquier otro player, como reserva. Hace falta porque no
--                 todos saben hacer todo: una pagina de YouTube en Firefox
--                 declara CanGoNext = false, asi que el boton de cancion
--                 siguiente cae solo en el player que si pueda (Spotify).
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl -p playerctld,%any next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl -p playerctld,%any play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl -p playerctld,%any play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl -p playerctld,%any previous"),   { locked = true })

-- Screenshots (grim + slurp + swappy)
hl.bind("Print",               hl.dsp.exec_cmd([[grim -g "$(slurp)" - | wl-copy]]))
hl.bind("CTRL + Print",        hl.dsp.exec_cmd([[grim - | wl-copy]]))
hl.bind("SHIFT + Print",       hl.dsp.exec_cmd([[mkdir -p "$HOME/Screenshots" && grim -g "$(slurp)" "$HOME/Screenshots/$(date +%Y%m%d-%H%M%S).png"]]))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd([[grim -g "$(slurp)" - | swappy -f -]]))


